mapper.select:
/* selectMasterMdctNewReBuyerAllList */ SELECT NVL(Y.DEPT, 'NULL') AS DEPT, DECODE(Y.DEPT, 'TOTAL', '합 계', '', '미지정', (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = Y.DEPT)) AS DEPT_NAME, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.C, 0)) AS CONTRACT_P_C, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.T, 0)) AS CONTRACT_P_T, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.F, 0)) AS CONTRACT_P_F, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.N, 0)) AS CONTRACT_P_N, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.C, 0)) AS CONTRACT_C_C, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.T, 0)) AS CONTRACT_C_T, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.F, 0)) AS CONTRACT_C_F, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.N, 0)) AS CONTRACT_C_N, SUM(Y.C+Y.T+Y.F+Y.N) AS CONTRACT_A_A, SUM(Y.C) AS CONTRACT_A_C, SUM(Y.T) AS CONTRACT_A_T, SUM(Y.F) AS CONTRACT_A_F, SUM(Y.N) AS CONTRACT_A_N, NVL(ROUND(SUM(Y.C) / DECODE(SUM(Y.C+Y.T+Y.F), 0, NULL, SUM(Y.C+Y.T+Y.F)) * 100, 1), 0) AS CONTRACT_A_RATE, SUM(Y.SHORT_TERM) AS SHORT_TERM, SUM(Y.MID_TERM) AS MID_TERM, SUM(Y.LONG_TERM) AS LONG_TERM, SUM(Y.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(Y.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(Y.CONTRACT_KIND_N) AS CONTRACT_KIND_N, Y.RANK FROM ( SELECT X.DEPT, X.CONTRACT_TYPE, SUM(X.PROCESS_STATUS_C) AS C, SUM(X.PROCESS_STATUS_T) AS T, SUM(X.PROCESS_STATUS_F) AS F, SUM(X.PROCESS_STATUS_N) AS N, SUM(X.SHORT_TERM) AS SHORT_TERM, SUM(X.MID_TERM) AS MID_TERM, SUM(X.LONG_TERM) AS LONG_TERM, SUM(X.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(X.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(X.CONTRACT_KIND_N) AS CONTRACT_KIND_N, 1 AS RANK FROM ( SELECT W.DEPT, W.CONTRACT_TYPE, W.PROCESS_STATUS_C, W.PROCESS_STATUS_T, W.PROCESS_STATUS_F, W.PROCESS_STATUS_N, CASE WHEN W.YEAR_CNT < 5 THEN 1 ELSE 0 END AS SHORT_TERM, CASE WHEN W.YEAR_CNT BETWEEN 5 AND 10 THEN 1 ELSE 0 END AS MID_TERM, CASE WHEN W.YEAR_CNT > 10 THEN 1 ELSE 0 END AS LONG_TERM, W.CONTRACT_KIND_R, W.CONTRACT_KIND_S, W.CONTRACT_KIND_N FROM ( SELECT (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE STATUS = 'C' AND YEAR = TO_CHAR(SYSDATE, 'YYYY') AND BUYER = B.CODE) AS DEPT, A.CONTRACT_TYPE, DECODE(A.PROCESS_STATUS, 'C', 1, 0) AS PROCESS_STATUS_C, DECODE(A.PROCESS_STATUS, 'T', 1, 0) AS PROCESS_STATUS_T, DECODE(A.PROCESS_STATUS, 'F', 1, 0) AS PROCESS_STATUS_F, DECODE(A.PROCESS_STATUS, NULL, 1, 0) AS PROCESS_STATUS_N, TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') START_YEAR, TO_CHAR(SYSDATE, 'YYYY') - TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') AS YEAR_CNT, DECODE(A.CONTRACT_KIND, 'R', 1, 0) AS CONTRACT_KIND_R, DECODE(A.CONTRACT_KIND, 'S', 1, 0) AS CONTRACT_KIND_S, DECODE(A.CONTRACT_KIND, NULL, 1, 0) AS CONTRACT_KIND_N FROM KEP_BUYER_ORG_MNG A, ICOMCOD2 B WHERE 1=1 AND A.ORG_CODE = B.TEXT1 AND B.COMPANY_CODE = 'KRKORE0001' AND B.TYPE = 'PFMP' AND B.FLAG = 'Y' AND A.STATUS IN ('C', 'R') ) W ) X GROUP BY X.DEPT, X.CONTRACT_TYPE
UNION ALL
SELECT 'TOTAL' AS DEPT, X.CONTRACT_TYPE, SUM(X.PROCESS_STATUS_C) AS C, SUM(X.PROCESS_STATUS_T) AS T, SUM(X.PROCESS_STATUS_F) AS F, SUM(X.PROCESS_STATUS_N) AS N, SUM(X.SHORT_TERM) AS SHORT_TERM, SUM(X.MID_TERM) AS MID_TERM, SUM(X.LONG_TERM) AS LONG_TERM, SUM(X.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(X.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(X.CONTRACT_KIND_N) AS CONTRACT_KIND_N, 2 AS RANK FROM ( SELECT W.DEPT, W.CONTRACT_TYPE, W.PROCESS_STATUS_C, W.PROCESS_STATUS_T, W.PROCESS_STATUS_F, W.PROCESS_STATUS_N, CASE WHEN W.YEAR_CNT < 5 THEN 1 ELSE 0 END AS SHORT_TERM, CASE WHEN W.YEAR_CNT BETWEEN 5 AND 10 THEN 1 ELSE 0 END AS MID_TERM, CASE WHEN W.YEAR_CNT > 10 THEN 1 ELSE 0 END AS LONG_TERM, W.CONTRACT_KIND_R, W.CONTRACT_KIND_S, W.CONTRACT_KIND_N FROM ( SELECT (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE STATUS = 'C' AND YEAR = TO_CHAR(SYSDATE, 'YYYY') AND BUYER = B.CODE) AS DEPT, A.CONTRACT_TYPE, DECODE(A.PROCESS_STATUS, 'C', 1, 0) AS PROCESS_STATUS_C, DECODE(A.PROCESS_STATUS, 'T', 1, 0) AS PROCESS_STATUS_T, DECODE(A.PROCESS_STATUS, 'F', 1, 0) AS PROCESS_STATUS_F, DECODE(A.PROCESS_STATUS, NULL, 1, 0) AS PROCESS_STATUS_N, TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') START_YEAR, TO_CHAR(SYSDATE, 'YYYY') - TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') AS YEAR_CNT, DECODE(A.CONTRACT_KIND, 'R', 1, 0) AS CONTRACT_KIND_R, DECODE(A.CONTRACT_KIND, 'S', 1, 0) AS CONTRACT_KIND_S, DECODE(A.CONTRACT_KIND, NULL, 1, 0) AS CONTRACT_KIND_N FROM KEP_BUYER_ORG_MNG A, ICOMCOD2 B WHERE 1=1 AND A.ORG_CODE = B.TEXT1 AND B.COMPANY_CODE = 'KRKORE0001' AND B.TYPE = 'PFMP' AND B.FLAG = 'Y' AND A.STATUS IN ('C', 'R') ) W ) X GROUP BY X.CONTRACT_TYPE ) Y GROUP BY Y.DEPT, Y.RANK ORDER BY Y.RANK, Y.DEPT

/* selectMasterMdctNewReBuyerIndvList */ SELECT NVL(Y.USER_ID, 'NULL') AS USER_ID, DECODE(Y.USER_ID, 'TOTAL', '합 계', '', '미지정', (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = Y.USER_ID)) AS USER_NAME, NVL(Y.DEPT, 'NULL') AS DEPT, DECODE(Y.DEPT, 'TOTAL', '합 계', '', '미지정', (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = Y.DEPT)) AS DEPT_NAME, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.C, 0)) AS CONTRACT_P_C, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.T, 0)) AS CONTRACT_P_T, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.F, 0)) AS CONTRACT_P_F, SUM(DECODE(Y.CONTRACT_TYPE, 'P', Y.N, 0)) AS CONTRACT_P_N, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.C, 0)) AS CONTRACT_C_C, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.T, 0)) AS CONTRACT_C_T, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.F, 0)) AS CONTRACT_C_F, SUM(DECODE(Y.CONTRACT_TYPE, 'C', Y.N, 0)) AS CONTRACT_C_N, SUM(Y.C+Y.T+Y.F+Y.N) AS CONTRACT_A_A, SUM(Y.C) AS CONTRACT_A_C, SUM(Y.T) AS CONTRACT_A_T, SUM(Y.F) AS CONTRACT_A_F, SUM(Y.N) AS CONTRACT_A_N, NVL(ROUND(SUM(Y.C) / DECODE(SUM(Y.C+Y.T+Y.F), 0, NULL, SUM(Y.C+Y.T+Y.F)) * 100, 1), 0) AS CONTRACT_A_RATE, SUM(Y.SHORT_TERM) AS SHORT_TERM, SUM(Y.MID_TERM) AS MID_TERM, SUM(Y.LONG_TERM) AS LONG_TERM, SUM(Y.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(Y.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(Y.CONTRACT_KIND_N) AS CONTRACT_KIND_N, Y.RANK FROM ( SELECT X.USER_ID, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = X.USER_ID) AS DEPT, X.CONTRACT_TYPE, SUM(X.PROCESS_STATUS_C) AS C, SUM(X.PROCESS_STATUS_T) AS T, SUM(X.PROCESS_STATUS_F) AS F, SUM(X.PROCESS_STATUS_N) AS N, SUM(X.SHORT_TERM) AS SHORT_TERM, SUM(X.MID_TERM) AS MID_TERM, SUM(X.LONG_TERM) AS LONG_TERM, SUM(X.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(X.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(X.CONTRACT_KIND_N) AS CONTRACT_KIND_N, 1 AS RANK FROM ( SELECT W.USER_ID, W.CONTRACT_TYPE, W.PROCESS_STATUS_C, W.PROCESS_STATUS_T, W.PROCESS_STATUS_F, W.PROCESS_STATUS_N, CASE WHEN W.YEAR_CNT < 5 THEN 1 ELSE 0 END AS SHORT_TERM, CASE WHEN W.YEAR_CNT BETWEEN 5 AND 10 THEN 1 ELSE 0 END AS MID_TERM, CASE WHEN W.YEAR_CNT > 10 THEN 1 ELSE 0 END AS LONG_TERM, W.CONTRACT_KIND_R, W.CONTRACT_KIND_S, W.CONTRACT_KIND_N FROM ( SELECT (SELECT MAX(KEP_USER_ID) FROM MIS_BUYER_MNG WHERE STATUS = 'C' AND YEAR = TO_CHAR(SYSDATE, 'YYYY') AND MAIN_CLERK = 'Y' AND BUYER = B.CODE) AS USER_ID, A.CONTRACT_TYPE, DECODE(A.PROCESS_STATUS, 'C', 1, 0) AS PROCESS_STATUS_C, DECODE(A.PROCESS_STATUS, 'T', 1, 0) AS PROCESS_STATUS_T, DECODE(A.PROCESS_STATUS, 'F', 1, 0) AS PROCESS_STATUS_F, DECODE(A.PROCESS_STATUS, NULL, 1, 0) AS PROCESS_STATUS_N, TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') START_YEAR, TO_CHAR(SYSDATE, 'YYYY') - TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') AS YEAR_CNT, DECODE(A.CONTRACT_KIND, 'R', 1, 0) AS CONTRACT_KIND_R, DECODE(A.CONTRACT_KIND, 'S', 1, 0) AS CONTRACT_KIND_S, DECODE(A.CONTRACT_KIND, NULL, 1, 0) AS CONTRACT_KIND_N FROM KEP_BUYER_ORG_MNG A, ICOMCOD2 B WHERE 1=1 AND A.ORG_CODE = B.TEXT1 AND B.COMPANY_CODE = 'KRKORE0001' AND B.TYPE = 'PFMP' AND B.FLAG = 'Y' AND A.STATUS IN ('C', 'R') ) W ) X GROUP BY X.USER_ID, X.CONTRACT_TYPE
UNION ALL
SELECT 'TOTAL' AS USER_ID, 'TOTAL' AS DEPT, X.CONTRACT_TYPE, SUM(X.PROCESS_STATUS_C) AS C, SUM(X.PROCESS_STATUS_T) AS T, SUM(X.PROCESS_STATUS_F) AS F, SUM(X.PROCESS_STATUS_N) AS N, SUM(X.SHORT_TERM) AS SHORT_TERM, SUM(X.MID_TERM) AS MID_TERM, SUM(X.LONG_TERM) AS LONG_TERM, SUM(X.CONTRACT_KIND_R) AS CONTRACT_KIND_R, SUM(X.CONTRACT_KIND_S) AS CONTRACT_KIND_S, SUM(X.CONTRACT_KIND_N) AS CONTRACT_KIND_N, 2 AS RANK FROM ( SELECT W.USER_ID, W.CONTRACT_TYPE, W.PROCESS_STATUS_C, W.PROCESS_STATUS_T, W.PROCESS_STATUS_F, W.PROCESS_STATUS_N, CASE WHEN W.YEAR_CNT < 5 THEN 1 ELSE 0 END AS SHORT_TERM, CASE WHEN W.YEAR_CNT BETWEEN 5 AND 10 THEN 1 ELSE 0 END AS MID_TERM, CASE WHEN W.YEAR_CNT > 10 THEN 1 ELSE 0 END AS LONG_TERM, W.CONTRACT_KIND_R, W.CONTRACT_KIND_S, W.CONTRACT_KIND_N FROM ( SELECT (SELECT MAX(KEP_USER_ID) FROM MIS_BUYER_MNG WHERE STATUS = 'C' AND YEAR = TO_CHAR(SYSDATE, 'YYYY') AND MAIN_CLERK = 'Y' AND BUYER = B.CODE) AS USER_ID, A.CONTRACT_TYPE, DECODE(A.PROCESS_STATUS, 'C', 1, 0) AS PROCESS_STATUS_C, DECODE(A.PROCESS_STATUS, 'T', 1, 0) AS PROCESS_STATUS_T, DECODE(A.PROCESS_STATUS, 'F', 1, 0) AS PROCESS_STATUS_F, DECODE(A.PROCESS_STATUS, NULL, 1, 0) AS PROCESS_STATUS_N, TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') START_YEAR, TO_CHAR(SYSDATE, 'YYYY') - TO_CHAR(TO_DATE(A.CONTRACT_FIRST_DATE, 'YYYYMMDD'), 'YYYY') AS YEAR_CNT, DECODE(A.CONTRACT_KIND, 'R', 1, 0) AS CONTRACT_KIND_R, DECODE(A.CONTRACT_KIND, 'S', 1, 0) AS CONTRACT_KIND_S, DECODE(A.CONTRACT_KIND, NULL, 1, 0) AS CONTRACT_KIND_N FROM KEP_BUYER_ORG_MNG A, ICOMCOD2 B WHERE 1=1 AND A.ORG_CODE = B.TEXT1 AND B.COMPANY_CODE = 'KRKORE0001' AND B.TYPE = 'PFMP' AND B.FLAG = 'Y' AND A.STATUS IN ('C', 'R') ) W ) X GROUP BY X.CONTRACT_TYPE ) Y GROUP BY Y.USER_ID, Y.DEPT, Y.RANK ORDER BY Y.RANK, Y.DEPT, Y.USER_ID
